  1	/**
  2	 * MINE//MIRAGE OpenEgiz bridge. One authoritative operations engine lives here.
  3	 * Simulated telemetry -> MQTT Ditto protocol -> Eclipse Ditto.
  4	 * Browser reads Ditto REST only via GET /api/twin; control requests never return
  5	 * computed state and become visible only after Ditto accepts MQTT updates.
  6	 */
  7	import http from 'node:http';
  8	import fs from 'node:fs';
  9	import path from 'node:path';
 10	import {fileURLToPath} from 'node:url';
 11	import mqtt from 'mqtt';
 12	import {MineOperations,SCENARIOS} from '../web/live/modules/operations.js';
 13	import {PLAYBOOKS} from '../web/live/modules/scenarios.js';
 14	import saryarka from '../web/live/maps/saryarka.js';
 15	import altai from '../web/live/maps/altai.js';
 16	
 17	const HERE=path.dirname(fileURLToPath(import.meta.url));
 18	const WEB=path.resolve(HERE,'../web');
 19	const MAPS={saryarka,altai};
 20	const NS='org.mine.mirage';
 21	const PORT=Number(process.env.PORT||5233);
 22	const DITTO=(process.env.DITTO_URL||'http://ditto-nginx:80').replace(/\/$/,'');
 23	const AUTH='Basic '+Buffer.from(`${process.env.DITTO_USER||'ditto'}:${process.env.DITTO_PASSWORD||''}`).toString('base64');
 24	const MQTT_HOST=process.env.MQTT_HOST||'mosquitto';
 25	const MQTT_PORT=Number(process.env.MQTT_PORT||1883);
 26	const ACTIONS=new Set([...SCENARIOS.map(s=>s[0]),...PLAYBOOKS.map(x=>'playbook:'+x.id),'cancelBlast','safety']);
 27	let currentMap='saryarka',ops=new MineOperations(MAPS[currentMap]),running=true,rate=1,connected=false;
 28	let lastPublish=0,lastError='';
 29	const broker=mqtt.connect(`mqtt://${MQTT_HOST}:${MQTT_PORT}`,{clientId:'mine-mirage-authority',reconnectPeriod:1500,connectTimeout:8000});
 30	broker.on('connect',()=>{connected=true;console.log('MQTT connected',MQTT_HOST);publish();});
 31	broker.on('reconnect',()=>{connected=false;});
 32	broker.on('offline',()=>{connected=false;});
 33	broker.on('error',e=>{lastError=String(e.message);console.error('MQTT',e.message);});
 34	function feature(value,unit){return {properties:unit?{value,unit}:{value}};}
 35	function publishTwin(id,features){
 36	  if(!connected)return;
 37	  const body={topic:`${NS}/${id}/things/twin/commands/modify`,path:'/features',value:features};
 38	  broker.publish(`telemetry/${id}`,JSON.stringify(body),{qos:1});
 39	}
 40	function publish(){
 41	  if(!connected)return;
 42	  const snap=ops.snapshot();
 43	  publishTwin('mine-01',{
 44	    state:feature(snap),
 45	    map:feature(snap.mapId),
 46	    simulation_time:feature(Math.round(snap.time*10)/10,'s'),
 47	    mined_tonnes:feature(snap.metrics.tonnes,'t'),
 48	    processed_tonnes:feature(snap.metrics.processed,'t'),
 49	    moving_trucks:feature(snap.metrics.moving),
 50	    energy:feature(snap.metrics.energyKwh??0,'kWh'),
 51	    running:feature(running),
 52	    speedup:feature(rate),
 53	    updated_at:feature(new Date().toISOString())
 54	  });
 55	  for(const t of snap.fleet){
 56	    publishTwin(t.id.toLowerCase(),{
 57	      state:feature(t.status),speed:feature(t.speed,'km/h'),
 58	      payload:feature(t.payload,'t'),fuel:feature(t.fuel,'%'),
 59	      health:feature(t.health,'%'),target:feature(t.target||''),
 60	      position:feature({x:t.position?.x||0,y:t.position?.y||0,z:t.position?.z||0})
 61	    });
 62	  }
 63	  for(const [id,a] of Object.entries(snap.assets)){
 64	    const key=a.id?.toLowerCase()||id;
 65	    publishTwin(key,{
 66	      state:feature(a.state||'idle'),
 67	      health:feature(a.health||0,'%'),
 68	      handled_tonnes:feature(a.handledTonnes||0,'t'),
 69	      operating_hours:feature(a.operatingHours||0,'h')
 70	    });
 71	  }
 72	  publishTwin('drill-01',{
 73	    phase:feature(snap.blast.phase),
 74	    drilled:feature(snap.blast.drilled||0),
 75	    holes:feature(snap.blast.holes||[]),
 76	    mwd_hardness:feature(snap.blast.hardnessIndex??0,'index'),
 77	    fragmentation:feature(snap.blast.fragmentation??0,'fraction'),
 78	    completed:feature(snap.blast.completed||0)
 79	  });
 80	  lastPublish=Date.now();
 81	}
 82	// Engine updates are SERVER ONLY. Clients never execute MineOperations.step.
 83	setInterval(()=>{
 84	  if(running)ops.step(1.5*rate);
 85	  publish();
 86	},1500).unref?.();
 87	
 88	const TYPES={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.glb':'model/gltf-binary','.json':'application/json','.png':'image/png','.jpg':'image/jpeg','.jpeg':'image/jpeg','.svg':'image/svg+xml','.ico':'image/x-icon','.md':'text/plain; charset=utf-8','.txt':'text/plain; charset=utf-8'};
 89	function json(res,status,obj){res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'});res.end(JSON.stringify(obj));}
 90	function parseBody(req){return new Promise((resolve,reject)=>{const chunks=[];let size=0;req.on('data',buf=>{size+=buf.length;if(size>16384){reject(Error('payload too large'));req.destroy();return;}chunks.push(buf);});req.on('end',()=>{try{resolve(JSON.parse(Buffer.concat(chunks).toString('utf8')||'{}'));}catch(e){reject(e)}});req.on('error',reject);});}
 91	async function getTwin(){
 92	  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),5500);
 93	  try{
 94	    const url=`${DITTO}/api/2/things/${encodeURIComponent(NS+':mine-01')}`;
 95	    const result=await fetch(url,{headers:{Authorization:AUTH,Accept:'application/json'},signal:controller.signal});
 96	    if(!result.ok)throw Error(`Ditto HTTP ${result.status}`);
 97	    const twin=await result.json();
 98	    const value=twin.features?.state?.properties?.value;
 99	    if(!value?.fleet||!value?.metrics)throw Error('Ditto twin not yet initialized by MQTT');
100	    return {snapshot:value,dittoThingId:twin.thingId,revision:twin._revision||0,updatedAt:twin.features?.updated_at?.properties?.value||null};
101	  }finally{clearTimeout(timer);}
102	}
103	async function serveFile(req,res,pathname){
104	  let decoded;
105	  try{decoded=decodeURIComponent(pathname);}catch{return json(res,400,{error:'bad path'});}
106	  const rel=decoded==='/'?'index.html':decoded.slice(1);
107	  const dest=path.resolve(WEB,rel);
108	  if(!(dest===WEB||dest.startsWith(WEB+path.sep)))return json(res,403,{error:'forbidden'});
109	  try{
110	    const stat=await fs.promises.stat(dest);
111	    if(!stat.isFile())return json(res,404,{error:'not a file'});
112	    res.writeHead(200,{'Content-Type':TYPES[path.extname(dest).toLowerCase()]||'application/octet-stream','Cache-Control':/\.(?:html|js|css)$/.test(dest)?'no-cache':'public, max-age=3600','X-Content-Type-Options':'nosniff'});
113	    fs.createReadStream(dest).pipe(res);
114	  }catch{return json(res,404,{error:'not found'});}
115	}
116	const server=http.createServer(async(req,res)=>{
117	  try{
118	    const uri=new URL(req.url||'/',`http://localhost:${PORT}`);
119	    if(req.method==='GET'&&uri.pathname==='/api/health'){
120	      return json(res,200,{service:'mine-mirage',mqttConnected:connected,map:currentMap,running,rate,lastPublish,platform:DITTO,lastError});
121	    }
122	    if(req.method==='GET'&&uri.pathname==='/api/twin'){
123	      try{return json(res,200,await getTwin());}
124	      catch(e){return json(res,503,{error:'Ditto data unavailable',detail:e.message});}
125	    }
126	    if(req.method==='POST'&&uri.pathname==='/api/command'){
127	      const {action}=await parseBody(req);
128	      if(typeof action!=='string'||!ACTIONS.has(action))return json(res,400,{error:'unknown action'});
129	      if(!connected)return json(res,503,{error:'MQTT not connected'});
130	      const applied=ops.action(action);publish();return json(res,202,{accepted:true,applied:Boolean(applied),source:'command queued to Ditto via MQTT'});
131	    }
132	    if(req.method==='POST'&&uri.pathname==='/api/control'){
133	      const body=await parseBody(req);
134	      if(body.operation==='toggle'){running=!running;}
135	      else if(body.operation==='reset'){ops=new MineOperations(MAPS[currentMap]);running=true;}
136	      else if(body.operation==='speed'&&[0.5,1,3,5].includes(body.rate)){rate=body.rate;}
137	      else if(body.operation==='map'&&MAPS[body.map]){currentMap=body.map;ops=new MineOperations(MAPS[currentMap]);running=true;}
138	      else return json(res,400,{error:'invalid control'});
139	      publish();return json(res,202,{accepted:true});
140	    }
141	    if(req.method!=='GET'&&req.method!=='HEAD')return json(res,405,{error:'method not allowed'});
142	    return serveFile(req,res,uri.pathname);
143	  }catch(e){console.error(e);return json(res,500,{error:String(e.message)});}
144	});
145	server.listen(PORT,'0.0.0.0',()=>console.log(`MINE//MIRAGE platform UI listening on ${PORT}`));

