base='http://127.0.0.1:'+os.environ['DITTO_PORT']+'/api/2/things/'
auth=base64.b64encode(('ditto:'+os.environ['DITTO_PASSWORD']).encode()).decode()
print(datetime.datetime.now().isoformat())
for id in ['ht-01','cr-01','cr-02','mine-01']:
 d=json.load(urllib.request.urlopen(urllib.request.Request(base+'org.mine.mirage:'+id,headers={'Authorization':'Basic '+auth}),timeout=8)); f={k:v['properties']['value'] for k,v in d['features'].items()}; s=f.pop('state',None)
 if id=='mine-01': print(id,d.get('_revision'),f,'metrics',s['metrics'],'flags',s['flags']); print('blocks',s['oreBlocks'])
 else: print(id,s,f)
PY

