 1	/** Conservative material / copper / water model. All rates are synthetic, in tonnes, m3, seconds. */
 2	import {clamp} from './network.js';
 3	export const PROCESS={hopperCapacity:360,waterPerTonne:.32,recovery:.89,concentrateGrade:.25,makeupRate:.12,recycleRate:1.5,pumpRate:.65};
 4	export const emptyCargo=()=>({mass:0,metal:0,hardness:0});
 5	export function take(cargo,amount){
 6	  const mass=Math.min(Math.max(0,amount),cargo.mass),ratio=cargo.mass>0?mass/cargo.mass:0;
 7	  const part={mass,metal:cargo.metal*ratio,hardness:cargo.hardness*ratio};
 8	  for(const k of ['mass','metal','hardness'])cargo[k]=Math.max(0,cargo[k]-part[k]);
 9	  return part;
10	}
11	export function add(target,part){for(const k of ['mass','metal','hardness'])target[k]+=part[k];}
12	export function initProduction(mine){
13	  mine.oreBlocks=Object.fromEntries(mine.faceIds.map((id,f)=>[id,Array.from({length:12},(_,i)=>{
14	    const grade=(f%2?.87:.57)+((i*7+f*3)%9)*.04;
15	    return {id:`${id}-B${String(i+1).padStart(2,'0')}`,reserve:1250+(i%4)*250,initial:1250+(i%4)*250,grade,hardness:.8+(i%5)*.12,fragmentation:.48};
16	  })]));
17	  mine.material={mined:emptyCargo(),external:emptyCargo(),processed:emptyCargo(),concentrate:emptyCargo(),tailings:emptyCargo(),initial:emptyCargo()};
18	  mine.buffers=Object.fromEntries(mine.crusherIds.map(id=>[id,{mass:mine.hopper[id],metal:mine.hopper[id]*mine.gradeFeed[id]/100,hardness:mine.hopper[id]}]));
19	  for(const t of mine.trucks){t.cargo={mass:t.payload,metal:t.payload*t.grade/100,hardness:t.payload};add(mine.material.initial,t.cargo);}
20	  for(const buffer of Object.values(mine.buffers))add(mine.material.initial,buffer);
21	  mine.water={reservoir:900,sump:160,pond:170,initial:1230,fresh:0,rain:0,evaporated:0,spilled:0,pumped:0,recycled:0,processUsed:0,sprayed:0,flow:0};
22	  mine.recycling=true;mine.trustAssay=true;mine.targetGrade=.8;
23	  mine.fuelDepot=15000;mine.fuelAdded=0;mine.fuelInitial=mine.trucks.reduce((a,t)=>a+t.fuelLitres,0)+mine.fuelDepot;
24	  mine.supplyJobs=[];
25	}
26	export function loadOre(mine,t,amount){
27	  let left=Math.max(0,Math.min(amount,t.capacity-t.payload)),loaded=0;
28	  for(const b of mine.oreBlocks[t.node]||[]){
29	    if(left<=1e-9)break;const mass=Math.min(left,b.reserve);if(mass<=0)continue;
30	    const part={mass,metal:mass*b.grade/100,hardness:mass*b.hardness*(1.35-.5*(b.fragmentation??.48))};b.reserve-=mass;left-=mass;loaded+=mass;
31	    add(t.cargo,part);add(mine.material.mined,part);
32	  }
33	  t.payload=t.cargo.mass;t.expectedPayload=t.payload;t.grade=t.payload>0?t.cargo.metal/t.payload*100:0;
34	  return loaded;
35	}
36	export function waterStep(mine,dt){
37	  const w=mine.water;const rain=mine.faults.rain?.68*dt:0;w.rain+=rain;w.sump+=rain;
38	  const fresh=mine.faults.waterShortage?0:Math.min(PROCESS.makeupRate*dt,1100-w.reservoir);w.fresh+=fresh;w.reservoir+=fresh;
39	  const pump=mine.faults.drainage&&!mine.faults.pumpFault&&!mine.faults.powerFault?Math.min(w.sump,PROCESS.pumpRate*dt,850-w.pond):0;
40	  w.sump-=pump;w.pond+=pump;w.pumped+=pump;
41	  const recycled=mine.recycling&&!mine.faults.powerFault?Math.min(w.pond,PROCESS.recycleRate*dt,1100-w.reservoir):0;
42	  w.pond-=recycled;w.reservoir+=recycled;w.recycled+=recycled;
43	  const energy=((pump>0?55:0)+(recycled>0?18:0))*dt/3600;mine.energyKwh+=energy;mine.cost+=energy*24;
44	  if(mine.faults.dustSuppression&&mine.fuelDepot>0&&w.reservoir>.018*dt){const spray=.018*dt;w.reservoir-=spray;w.evaporated+=spray;w.sprayed+=spray;mine.dust=clamp(mine.dust-.024*dt,.04,.98);}
45	  if(w.sump>650){w.spilled+=w.sump-650;w.sump=650;}
46	  if(w.pond>850){w.spilled+=w.pond-850;w.pond=850;}
47	  w.flow=0;
48	}
49	export function processOre(mine,dt){
50	  mine.powerDemand=0;
51	  for(const id of mine.crusherIds){
52	    const asset=mine.assets[id],i=mine.crusherIds.indexOf(id),buffer=mine.buffers[id];
53	    const offline=mine.faults.powerFault||mine.faults.beltFault||(i===0&&mine.faults.crusherFault)||(i===1&&mine.faults.crusherBFault);
54	    const hardness=buffer.mass>0?buffer.hardness/buffer.mass:1;
55	    const availableWater=Math.max(0,850-mine.water.pond)/PROCESS.waterPerTonne;
56	    let rate=asset.rate/Math.max(.7,hardness)*(mine.faults.heat?.9:1)*Math.max(.55,Math.min(1,asset.health/90));
57	    const amount=offline?0:Math.min(buffer.mass,rate*dt,mine.water.reservoir/PROCESS.waterPerTonne,availableWater);
58	    asset.state=offline?'offline':amount>0?'running':buffer.mass<.01?'starved':'water-limited';
59	    if(amount>0){
60	      const part=take(buffer,amount);add(mine.material.processed,part);
61	      const realGrade=part.metal/part.mass*100;
62	      const reportedGrade=realGrade+(mine.faults.assayFault?.4:0);
63	      const controlledGrade=mine.trustAssay?realGrade:reportedGrade;
64	      const recovery=clamp(PROCESS.recovery-Math.abs(controlledGrade-mine.targetGrade)*.09-(hardness-1)*.03,.65,.93);
65	      const copper=part.metal*recovery,concMass=copper/PROCESS.concentrateGrade;
66	      add(mine.material.concentrate,{mass:concMass,metal:copper,hardness:0});
67	      add(mine.material.tailings,{mass:part.mass-concMass,metal:part.metal-copper,hardness:part.hardness});
68	      mine.processed+=amount;mine.copper+=copper;
69	      const water=amount*PROCESS.waterPerTonne;mine.water.reservoir-=water;mine.water.pond+=water*.92;mine.water.evaporated+=water*.08;mine.water.processUsed+=water;mine.water.flow+=water/dt;
70	      const energy=amount*1.15*hardness;mine.energyKwh+=energy;mine.cost+=amount*38+energy*24;mine.powerDemand+=energy/dt*3600;
71	      asset.operatingHours=(asset.operatingHours||0)+dt/3600;asset.handledTonnes=(asset.handledTonnes||0)+amount;asset.energyKwh=(asset.energyKwh||0)+energy;asset.health=Math.max(0,asset.health-amount*hardness*.00016);
72	    }
73	    mine.hopper[id]=buffer.mass;mine.gradeFeed[id]=buffer.mass>0?buffer.metal/buffer.mass*100:0;
74	  }
75	}
76	export function productionMetrics(mine){
77	  const p=mine.material,w=mine.water;
78	  const cargo=mine.trucks.reduce((a,t)=>{add(a,t.cargo);return a;},emptyCargo());
79	  const buffer=Object.values(mine.buffers).reduce((a,t)=>{add(a,t);return a;},emptyCargo());
80	  return {
81	    mined:p.mined.mass,copperTonnes:mine.copper,recoveryPct:p.processed.metal?100*p.concentrate.metal/p.processed.metal:0,
82	    feedGradePct:p.processed.mass?p.processed.metal/p.processed.mass*100:0,
83	    reserveTonnes:Object.values(mine.oreBlocks).flat().reduce((a,b)=>a+b.reserve,0),
84	    massError:p.initial.mass+p.mined.mass+p.external.mass-cargo.mass-buffer.mass-p.concentrate.mass-p.tailings.mass,
85	    metalError:p.initial.metal+p.mined.metal+p.external.metal-cargo.metal-buffer.metal-p.concentrate.metal-p.tailings.metal,
86	    waterError:w.initial+w.fresh+w.rain-w.evaporated-w.spilled-w.reservoir-w.sump-w.pond,
87	    waterReservoir:w.reservoir,waterSump:w.sump,waterPond:w.pond,waterRecycled:w.recycled,
88	    fuelBalanceError:mine.fuelInitial+mine.fuelAdded-mine.fuelConsumed-mine.fuelDepot-mine.trucks.reduce((a,t)=>a+t.fuelLitres,0),
89	    unitCost:mine.processed>0?mine.cost/mine.processed:0,availabilityPct:100*mine.trucks.filter(t=>!['stranded','towing','repairing','to_workshop'].includes(t.status)).length/mine.trucks.length,
90	  };
91	}
 1	/** Educational drill-and-blast cycle. Synthetic MWD indices; NOT blast-design data. */
 2	const clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
 3	export const BLAST_PHASES={idle:'Участок доступен',drilling:'Бурение скважин',charging:'Контроль готовности',evacuation:'Эвакуация и контроль периметра',countdown:'Защитный отсчёт',ventilation:'Проветривание и осмотр'};
 4	
 5	export function createBlastState(mine){
 6	  const blocks=mine.oreBlocks[mine.faceIds[0]]||[];
 7	  const mean=blocks.reduce((s,b)=>s+b.hardness,0)/Math.max(1,blocks.length);
 8	  const holes=Array.from({length:20},(_,i)=>{
 9	    const row=Math.floor(i/5),col=i%5;
10	    const variance=(((i*17+row*3+col*5)%13)-6)*.024;
11	    const rockIndex=clamp(Math.round(100*(.47+(mean-1)*.52+variance)),14,91);
12	    return {id:`MWD-${String(i+1).padStart(2,'0')}`,row,col,status:'planned',rockIndex,
13	      penetrationIndex:clamp(100-rockIndex+12,8,100),torqueIndex:clamp(rockIndex+7,0,100)};
14	  });
15	  return {phase:'idle',timer:0,reason:'',completed:0,holes,drilled:0,checked:0,
16	    hardnessIndex:null,fragmentation:0.48,coarsePct:52,cycle:0,detonatedAt:null,
17	    note:'Все MWD-параметры и показатели фрагментации синтетические; проектирования взрывов нет.'};
18	}
19	
20	export function completeBlast(mine){
21	  const b=mine.blast;
22	  // Abstract fragmentation index; hardness produces coarser fragments.
23	  const fragment=clamp(.94-b.hardnessIndex*.0048,.43,.87);
24	  b.fragmentation=Number(fragment.toFixed(3));b.coarsePct=Math.round((1-fragment)*100);
25	  b.holes.forEach(h=>h.status='fired');b.detonatedAt=mine.time;
26	  // Effect is applied to remaining material of the actual northern working face.
27	  for(const block of mine.oreBlocks[mine.faceIds[0]]||[])block.fragmentation=fragment;
28	  return b;
29	}
30	
31	export function loadingFragmentationFactor(block){
32	  return clamp(.67+.67*(block?.fragmentation??.48),.67,1.30);
33	}

