  1	"""Idempotent, automatic creation of MINE//MIRAGE twins inside Eclipse Ditto."""
  2	import base64
  3	import json
  4	import os
  5	import time
  6	import urllib.request
  7	import urllib.error
  8	
  9	URL=os.environ.get('DITTO_URL','http://ditto-nginx:80').rstrip('/')
 10	USER=os.environ.get('DITTO_USER','ditto')
 11	PASSWORD=os.environ['DITTO_PASSWORD']
 12	NS='org.mine.mirage'
 13	AUTH='Basic '+base64.b64encode(f'{USER}:{PASSWORD}'.encode()).decode()
 14	
 15	def make(name,kind,features,extra=None,parent=True):
 16	    attrs={'name':name,'kind':kind,'_isType':False}
 17	    if parent: attrs['_parents']=f'{NS}:mine-01'
 18	    if extra: attrs.update(extra)
 19	    return {'policyId':'default:basic_policy','attributes':attrs,'features':{
 20	        k:{'properties':{'value':v}} for k,v in features.items()
 21	    }}
 22	
 23	def twins():
 24	    t={'mine-01':make('MINE//MIRAGE · цифровой карьер','mine',{'state':{},'map':'saryarka','running':True},parent=False)}
 25	    for i in range(1,15):
 26	        t[f'ht-{i:02d}']=make(f'Haul truck HT-{i:02d}','haul-truck',{'state':'parked','speed':0,'payload':0,'fuel':100})
 27	    for i in range(1,3):
 28	        t[f'ex-{i:02d}']=make(f'Excavator EX-{i:02d}','excavator',{'state':'idle','handled_tonnes':0})
 29	        t[f'cr-{i:02d}']=make(f'Crusher CR-{i:02d}','crusher',{'state':'idle','handled_tonnes':0})
 30	    t['drill-01']=make('MWD drill rig · BVR','drill',{'phase':'idle','drilled':0,'holes':[],'fragmentation':0})
 31	    return {f'{NS}:{key}':val for key,val in t.items()}
 32	
 33	def main():
 34	    data=twins()
 35	    for tid,body in data.items():
 36	        req=urllib.request.Request(f'{URL}/api/2/things/{tid}',method='PUT',data=json.dumps(body).encode(),headers={'Authorization':AUTH,'Content-Type':'application/json'})
 37	        for attempt in range(60):
 38	            try:
 39	                with urllib.request.urlopen(req,timeout=25) as res:
 40	                    print(f'Created twin {tid}: HTTP {res.status}',flush=True)
 41	                    break
 42	            except (urllib.error.URLError,TimeoutError) as e:
 43	                if attempt==59:raise RuntimeError(f'Cannot create {tid}: {e}') from e
 44	                time.sleep(3)
 45	    print(f'{len(data)} MINE//MIRAGE twins ready in Eclipse Ditto',flush=True)
 46	
 47	if __name__=='__main__':main()

